const fs=require('node:fs');
const assert=require('node:assert/strict');
const media=fs.readFileSync('app/src/main/java/com/openlocal/office/core/FgMediaPlayer.java','utf8');
const book=fs.readFileSync('app/src/main/assets/epub-reader.js','utf8');
const archive=fs.readFileSync('app/src/main/assets/universal-reader.js','utf8');
const lib=fs.readFileSync('app/src/main/assets/premium-library.js','utf8');
const style=fs.readFileSync('app/src/main/assets/style.css','utf8');
const gradle=fs.readFileSync('app/build.gradle.kts','utf8');
assert.match(media,/RESIZE_MODE_FIT/,'Preserve the entire video at its native aspect ratio by default');
assert.match(media,/new android\.view\.ScaleGestureDetector/,'Pinch zoom must handle two pointers');
assert.match(media,/videoScale\[0\]\*detector\.getScaleFactor/,'Video magnification must be adjustable');
assert.match(media,/display\.setScaleX\(scale\);display\.setScaleY\(scale\)/,'Zoom must affect video');
assert.match(media,/display\.setTranslationX\(videoX\[0\]\)/,'Magnified video must support panning');
assert.match(media,/videoScale\[0\]=1f;videoX\[0\]=0f/,'Double tap must restore full-screen zoom baseline');
assert.match(media,/final View orientation=new View\(activity\)/,'Native phone orientation vector');
assert.match(media,/final View lock=new View\(activity\)/,'Native lock icon');
assert.match(media,/rotationLocked\[0\]=!rotationLocked\[0\]/,'Lock must toggle');
assert.doesNotMatch(media,/Share video with Android/,'Player must not show unwanted sharing');
assert.doesNotMatch(media,/smallChromeIcon\("◇"/,'Tilted diamond icon must not return');
assert.match(media,/final VideoTransport previous=new VideoTransport/,'Native transport controls');
assert.match(media,/forceImmersiveBars\(\)/,'Immersive controls retained');
assert.match(media,/new int\[\]\{0xb5000000,0x42000000,0x00000000\}/,'Subtle top fade instead of opaque strip');
assert.match(book,/rootMargin:'140% 0px'/,'EPUB upcoming chapters load earlier');
assert.match(archive,/const MAX_IMAGE_FETCHES=3/,'ZIP image prefetch remains bounded');
assert.match(archive,/rootMargin:'65% 0px'/,'ZIP image prefetch begins before viewport');
assert.match(lib,/search\.placeholder='Search your books'/,'Library presentation restored');
assert.match(lib,/welcome\.hidden=true;dashboard\.hidden=true/,'Home stays removed');
assert.match(style,/repeat\(3,minmax\(0,1fr\)\)!important/,'Preserve restored original library sizing');
assert.match(gradle,/versionCode\s*=\s*38/);
assert.match(gradle,/versionName\s*=\s*"0\.15\.16"/);
